// ====== REGISTRY — every content file calls one of these functions; nothing else is global ======
// Files are loaded in the order listed by abc/manifest.js (generated by `node tools/check.js --fix`).
var ABC = {
  config: null,      // abc/config.js: active languages + module order
  langs: {},         // code → { grammar…, strings, words[], info{} }   (abc/lang/<code>/*)
  concepts: [],      // language-neutral concepts (abc/concepts.js)
  conceptById: {},
  modules: [],       // subjects (abc/modules/<id>/module.js)
  views: {},         // screen types (abc/core/views/*.js)
  games: {},         // game types (abc/core/games/*.js)
  errors: []         // problems found while loading (duplicates…) — tools/check.js fails on them
};
const abcLang = code => ABC.langs[code] || (ABC.langs[code] = { code, strings: {}, words: [], info: {} });
const abcMerge = (a, b) => { for (const k in b) a[k] = (b[k] && typeof b[k] === 'object' && !Array.isArray(b[k]) && typeof a[k] === 'object') ? abcMerge(a[k], b[k]) : b[k]; return a; };

function CONFIG(c) { ABC.config = c; }
// language meta + grammar (abc/lang/<code>/grammar.js)
function LANG(code, def) { Object.assign(abcLang(code), def); }
// UI strings of a language (abc/lang/<code>/strings.js)
function STRINGS(code, s) { abcMerge(abcLang(code).strings, s); }
// words of a language (abc/lang/<code>/words.js):  const w = WORDS('ro');  w('cow', { w: 'va/că', … });
function WORDS(code) {
  const L = abcLang(code), seen = new Set(L.words.map(x => x.id));
  return (id, e) => {
    if (seen.has(id)) ABC.errors.push(`${code}/words: "${id}" defined twice`);
    seen.add(id); L.words.push(Object.assign({ id }, e));
  };
}
// "What is it?" cards of a language (abc/lang/<code>/info.js):  const i = INFO('ro');  i('rainbow', { title, lines });
function INFO(code) {
  const L = abcLang(code);
  return (id, card) => { if (L.info[id]) ABC.errors.push(`${code}/info: "${id}" defined twice`); L.info[id] = card; };
}
// a concept (abc/concepts.js): stable ASCII id, picture, optional { gloss, cats }
function C(id, pic, opts) {
  if (ABC.conceptById[id]) ABC.errors.push(`concepts: "${id}" defined twice`);
  const c = Object.assign({ id, pic, order: ABC.concepts.length }, opts);
  ABC.concepts.push(c); ABC.conceptById[id] = c;
}
// a subject module (abc/modules/<id>/module.js) and its strings per language (abc/modules/<id>/lang/<code>.js)
function MODULE(id, def) { ABC.modules.push(Object.assign({ id, strings: {} }, def)); }
function MSTRINGS(id, code, s) {
  const m = ABC.modules.find(m => m.id === id);
  if (!m) { ABC.errors.push(`module strings for unknown module "${id}"`); return; }
  m.strings[code] = abcMerge(m.strings[code] || {}, s);
}
// a screen type and a game type (abc/core/views/*.js, abc/core/games/*.js)
function VIEW(id, def) { ABC.views[id] = Object.assign({ id }, def); }
function GAME(id, def) { ABC.games[id] = Object.assign({ id }, def); }
